@f1 w.request.filler text="showed Sales by month to the team; they were fine with the numbers but not how it reads at a glance, so as a first fix"
@f2 w.request.filler text="then we look again next week"
@r1 w.request.request act=change mood=do words="make the error bars red" predicate=make
@r1.t w.request.target request=$r1 family=chart mode=existing determiner=definite fill=context
